impl ::flatbuffers::Verifiable for Envelope<'_> {
  #[inline]
  fn run_verifier(
    v: &mut ::flatbuffers::Verifier, pos: usize
  ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
    v.visit_table(pos)?
     .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("protocol_version", Self::VT_PROTOCOL_VERSION, false)?
     .visit_union::<Message, _>("message_type", Self::VT_MESSAGE_TYPE, "message", Self::VT_MESSAGE, false, |key, v, pos| {
        match key {
          Message::GameSpec => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<GameSpec>>("Message::GameSpec", pos),
          Message::Observation => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<Observation>>("Message::Observation", pos),
          Message::Action => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<Action>>("Message::Action", pos),
          Message::Event => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<Event>>("Message::Event", pos),
          Message::MatchHeader => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<MatchHeader>>("Message::MatchHeader", pos),
          Message::MatchResult => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<MatchResult>>("Message::MatchResult", pos),
          Message::Profile => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<Profile>>("Message::Profile", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
